class Solution:
    def canFinish(self, n: int, pre: List[List[int]]) -> bool:
        # build adjacent list and in_degree list
        graph = defaultdict(list)
        in_degree = [0] * n
        for u, v in pre:
            graph[v].append(u)
            in_degree[u] += 1

        # take no pre courses to queue
        queue = deque()
        for course in range(n):
            if in_degree[course] == 0:
                queue.append(course)

        ans = []
        while queue:
            m = len(queue)
            for _ in range(m):
                node = queue.popleft()
                ans.append(node)
                for nei in graph[node]:
                    in_degree[nei] -= 1
                    if in_degree[nei] == 0:
                        queue.append(nei)

        if len(ans) < n:
            return False
        return True
